import { Redis } from "ioredis";
import { env } from "./env.js";

export let redis: Redis = {} as any;

if (env.USE_REDIS) {
  redis = new Redis({
    family: 6,
    port: 6379,
    password: env.REDIS_PASSWORD,
    host: env.REDIS_HOST,
  });
}

import { V1Input } from "./schema.js";

// Change this when you want to manually bust the cache
const CACHE_BUSTER = "v1";

export const createCacheKey = (item: V1Input) => {
  const cacheKey = JSON.stringify({
    code: item.code,
    lang: item.lang,
    meta: item.meta,
    _key: CACHE_BUSTER,
  });
  return cacheKey;
};

import { V1Input } from "./schema.js";

export interface QueueItem {
  input: V1Input;
  onDone: (result: string) => void;
  onError: () => void;
}

import bodyParser from "body-parser";
import express from "express";
import { v1POST } from "./server/v1/POST.js";

const app = express();
const port = 3000;

app.use(bodyParser.json());

app.get("/", (req, res) => {
  res.send("Healthy!");
});

app.post("/v1", v1POST);

const start = async () => {
  app.listen(port, () =>
    console.log(`Shiki Service listening on port ${port}!`),
  );
};

start().catch(async (e) => {
  console.log(e);
  process.exit(1);
});

import { z } from "zod";

export const v1SchemaInput = z.object({
  code: z.string(),
  lang: z.string(),
  meta: z.string().optional().nullable().default(""),
  theme: z.string().optional().default("github-dark"),
});

export type V1Input = z.infer<typeof v1SchemaInput>;

export const environmentSchema = z.object({
  AUTHORIZATION: z.string(),
  REDIS_PASSWORD: z.string(),
  REDIS_HOST: z.string(),
  USE_REDIS: z
    .string()
    .optional()
    .transform((v) => v === "true"),
});

export type Environment = z.infer<typeof environmentSchema>;

